<?php
namespace App\Livewire\Admin\Receivables;
use App\Models\Invoice; use Livewire\Attributes\Url; use Livewire\Component; use Livewire\WithPagination;
class Index extends Component{use WithPagination;#[Url]public string $search='';#[Url]public string $status='';public function render(){$user=auth()->user();abort_unless($user->canViewReceivables(),403);$q=Invoice::query()->visibleToUser($user)->with('lead')->where('balance_amount','>',0)->when($this->status==='overdue',fn($q)=>$q->whereDate('due_date','<',today()))->when($this->search,fn($q)=>$q->where(fn($q)=>$q->where('invoice_number','like','%'.$this->search.'%')->orWhereHas('lead',fn($q)=>$q->where('customer_name','like','%'.$this->search.'%'))));$summary=['outstanding'=>(clone $q)->sum('balance_amount'),'overdue'=>(clone $q)->whereDate('due_date','<',today())->sum('balance_amount'),'count'=>(clone $q)->count()];return view('livewire.admin.receivables.index',['invoices'=>$q->orderBy('due_date')->paginate(25),'summary'=>$summary])->layout('components.layouts.admin',['title'=>'Receivables']);}}
